# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GENETİK MÜHENDİSLİĞİ VE BİYOTEKNOLOJİ İLİŞKİSİ</text>\n  <rect x="25" y="50" width="295" height="188" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="172" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1d4ed8">Genetik Mühendisliği (Bilim / Yöntem)</text>\n  <text x="40" y="102" font-size="11.5" fill="#334155">• DNA ve genler üzerinde doğrudan</text>\n  <text x="48" y="119" font-size="11.5" fill="#334155">değişiklik yapan bilim alanıdır.</text>\n  <text x="40" y="144" font-size="11.5" fill="#334155">• Genlerin tespiti, kesilmesi, çoğaltılması</text>\n  <text x="48" y="161" font-size="11.5" fill="#334155">ve başka canlıya aktarılmasını sağlar.</text>\n  <text x="40" y="188" font-size="11.5" font-weight="bold" fill="#1e3a8a">Örnek: İnsan insülin geninin kesilerek</text>\n  <text x="48" y="206" font-size="11.5" font-weight="bold" fill="#1e3a8a">bakteri DNA\'sına (plazmitine) aktarılması</text>\n  <path d="M 325 144 L 372 144" stroke="#0f172a" stroke-width="2.5"/>\n  <polygon points="368,138 380,144 368,150" fill="#0f172a"/>\n  <rect x="380" y="50" width="295" height="188" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="527" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#15803d">Biyoteknoloji (Üretim / Teknoloji)</text>\n  <text x="395" y="102" font-size="11.5" fill="#334155">• Canlı hücreleri ve genetik mühendisliği</text>\n  <text x="403" y="119" font-size="11.5" fill="#334155">yöntemlerini kullanarak <tspan font-weight="bold">ürün</tspan> geliştirir.</text>\n  <text x="395" y="144" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Geleneksel:</tspan> Yoğurt, peynir, sirke, ıslah</text>\n  <text x="395" y="166" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Modern:</tspan> Aşı, ilaç, antikor, GDO üretimi</text>\n  <text x="395" y="192" font-size="11.5" font-weight="bold" fill="#14532d">Örnek: Gen aktarılmış bakterilerden</text>\n  <text x="403" y="210" font-size="11.5" font-weight="bold" fill="#14532d">endüstriyel ölçekte insülin ilacı üretilmesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAŞLICA GENETİK MÜHENDİSLİĞİ VE BİYOTEKNOLOJİ UYGULAMALARI</text>\n  <rect x="20" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="97" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Gen Aktarımı</text>\n  <text x="30" y="96" font-size="10.5" fill="#334155">Bir canlıdaki genin</text>\n  <text x="30" y="112" font-size="10.5" fill="#334155">başka bir canlıya</text>\n  <text x="30" y="128" font-size="10.5" fill="#334155">aktarılmasıdır.</text>\n  <text x="30" y="156" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Ateş böceği geni</text>\n  <text x="36" y="172" font-size="10.5" fill="#1e3a8a">→ Tütün bitkisi</text>\n  <text x="30" y="194" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Bakteride insülin</text>\n  <text x="36" y="210" font-size="10.5" fill="#1e3a8a">hormonu üretimi</text>\n  <rect x="188" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="265" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Gen Tedavisi</text>\n  <text x="198" y="96" font-size="10.5" fill="#334155">Hastalığa yol açan</text>\n  <text x="198" y="112" font-size="10.5" fill="#334155">bozuk genin sağlıklı</text>\n  <text x="198" y="128" font-size="10.5" fill="#334155">genle değiştirilmesi</text>\n  <text x="198" y="144" font-size="10.5" fill="#334155">veya engellenmesidir.</text>\n  <text x="198" y="174" font-size="10.5" font-weight="bold" fill="#14532d">• Kalıtsal hastalıklar</text>\n  <text x="198" y="194" font-size="10.5" font-weight="bold" fill="#14532d">• Kanser hücrelerinin</text>\n  <text x="204" y="210" font-size="10.5" fill="#14532d">durdurulması</text>\n  <rect x="356" y="48" width="155" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="433" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Klonlama</text>\n  <text x="366" y="96" font-size="10.5" fill="#334155">Vücut hücresi çekirdeği</text>\n  <text x="366" y="112" font-size="10.5" fill="#334155">çekirdeksiz yumurtaya</text>\n  <text x="366" y="128" font-size="10.5" fill="#334155">aktarılarak genetik</text>\n  <text x="366" y="144" font-size="10.5" fill="#334155">ikiz elde edilir.</text>\n  <text x="366" y="174" font-size="10.5" font-weight="bold" fill="#854d0e">• Koyun Dolly (1996)</text>\n  <text x="366" y="194" font-size="10.5" fill="#713f12">• Çekirdek kiminse</text>\n  <text x="372" y="210" font-size="10.5" fill="#713f12">klon onun ikizidir!</text>\n  <rect x="524" y="48" width="155" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="601" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">4. Islah ve Aşılama</text>\n  <text x="534" y="96" font-size="10.5" fill="#334155">Üstün özellikli bitki</text>\n  <text x="534" y="112" font-size="10.5" fill="#334155">ve hayvanların seçilip</text>\n  <text x="534" y="128" font-size="10.5" fill="#334155">çaprazlanmasıyla</text>\n  <text x="534" y="144" font-size="10.5" fill="#334155">verimli döl elde edilir.</text>\n  <text x="534" y="174" font-size="10.5" font-weight="bold" fill="#9d174d">• Bol süt veren inek</text>\n  <text x="534" y="194" font-size="10.5" font-weight="bold" fill="#9d174d">• Soğuğa dirençli</text>\n  <text x="540" y="210" font-size="10.5" fill="#9d174d">buğday tohumu</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİYOTEKNOLOJİNİN YARARLI VE ZARARLI YÖNLERİ (İKİLEMLER)</text>\n  <rect x="25" y="50" width="315" height="188" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#15803d">Olumlu (Yararlı) Etkileri</text>\n  <text x="40" y="102" font-size="11.5" fill="#334155">✓ Aşı, antibiyotik, insülin, büyüme hormonu</text>\n  <text x="52" y="119" font-size="11.5" fill="#334155">ve vitaminlerin ucuz ve hızlı üretilmesi</text>\n  <text x="40" y="143" font-size="11.5" fill="#334155">✓ Kuraklığa, böceklere dayanıklı ve raf ömrü</text>\n  <text x="52" y="160" font-size="11.5" fill="#334155">uzun tarım ürünlerinin yetiştirilmesi</text>\n  <text x="40" y="184" font-size="11.5" fill="#334155">✓ Kirli suları ve petrol atıklarını temizleyen</text>\n  <text x="52" y="201" font-size="11.5" fill="#334155">bakterilerin geliştirilmesi, kök hücre tedavisi</text>\n  <rect x="360" y="50" width="315" height="188" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#b91c1c">Olumsuz (Zararlı) Etkileri ve Riskler</text>\n  <text x="375" y="102" font-size="11.5" fill="#334155">✗ GDO\'lu besinlerin insanlarda alerjik</text>\n  <text x="387" y="119" font-size="11.5" fill="#334155">reaksiyonlara ve antibiyotik direncine yol açması</text>\n  <text x="375" y="143" font-size="11.5" fill="#334155">✗ Doğal tozlaşmayla yabani türlere gen kaçışı</text>\n  <text x="387" y="160" font-size="11.5" fill="#334155">olması, ekolojik dengenin ve biyoçeşitliliğin zarar görmesi</text>\n  <text x="375" y="184" font-size="11.5" fill="#334155">✗ Tohumda dışa bağımlılık, biyolojik silah</text>\n  <text x="387" y="201" font-size="11.5" fill="#334155">tehlikesi ve etik / ahlaki tartışmalar</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
